import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [compareIds, setCompareIds] = useState([]); // Храним только ID выбранных для сравнения авто
  const [loading, setLoading] = useState(true);
  
  // Состояния для редактирования профиля
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  // Состояния для отправки отзывов по тест-драйвам
  const [reviewForm, setReviewForm] = useState({
    test_drive_id: null,
    rating: 5,
    comment: ''
  });

  // Состояние для отслеживания распечатываемого в данный момент чека
  const [printingId, setPrintingId] = useState(null);

  const tabs = [
    { key: 'profile', label: 'Профиль' },
    { key: 'purchases', label: 'История покупок' },
    { key: 'test_drives', label: 'Тест-драйвы' },
    { key: 'loans', label: 'Заявки на кредит' },
    { key: 'favorites', label: 'Избранное' },
    { key: 'compare', label: 'Сравнение' },
    { key: 'notifications', label: 'Уведомления' }
  ];

  const fetchData = useCallback(async () => {
    try {
      const [resP, resT, resL, resF] = await Promise.all([
        api.get('/api/purchases'),
        api.get('/api/testdrives'),
        api.get('/api/loans'),
        api.get('/api/favorites')
      ]);
      setPurchases(resP.data);
      setTestDrives(resT.data);
      setLoans(resL.data);
      setFavorites(resF.data);

      const savedCompare = JSON.parse(localStorage.getItem('compareList') || '[]');
      setCompareIds(savedCompare.map(c => c.id));
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/api/auth/update-profile', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен!' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: err.response?.data?.detail || 'Ошибка при обновлении профиля' });
    }
  };

  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/api/testdrives/review', reviewForm);
      alert('Отзыв успешно отправлен!');
      setReviewForm({ test_drive_id: null, rating: 5, comment: '' });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Ошибка при отправке отзыва');
    }
  };

  const handleRemoveFavorite = async (carId) => {
    try {
      await api.delete(`/api/favorites/${carId}`);
      setFavorites(prev => prev.filter(f => f.id !== carId));
    } catch (err) {
      console.error(err);
    }
  };

  const handleRemoveCompare = (carId) => {
    const savedCompare = JSON.parse(localStorage.getItem('compareList') || '[]');
    const updated = savedCompare.filter(c => c.id !== carId);
    localStorage.setItem('compareList', JSON.stringify(updated));
    setCompareIds(updated.map(c => c.id));
  };

  // Функция для контролируемой печати конкретного чека
  const handlePrintReceipt = (id) => {
    setPrintingId(id);
    setTimeout(() => {
      window.print();
      setPrintingId(null);
    }, 50);
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'profile':
        return (
          <div className={styles.profileSection}>
            <div className={styles.card}>
              <h3>Личные данные</h3>
              <form onSubmit={handleProfileUpdate} className={styles.form}>
                <div className={styles.formGroup}>
                  <label>ФИО</label>
                  <input
                    type="text"
                    value={profileForm.full_name}
                    onChange={(e) => setProfileForm(prev => ({ ...prev, full_name: e.target.value }))}
                    required
                  />
                </div>
                <div className={styles.formGroup}>
                  <label>Телефон</label>
                  <input
                    type="text"
                    value={profileForm.phone}
                    onChange={(e) => setProfileForm(prev => ({ ...prev, phone: e.target.value }))}
                    required
                  />
                </div>
                <button type="submit" className={styles.saveBtn}>Сохранить изменения</button>
                {updateStatus && (
                  <p className={updateStatus.type === 'success' ? styles.successText : styles.errorText}>
                    {updateStatus.text}
                  </p>
                )}
              </form>
            </div>
          </div>
        );

      case 'purchases':
        return purchases.length > 0 ? (
          <div className={styles.cardsGrid}>
            {purchases.map((p, idx) => (
              <div 
                key={p.id} 
                className={`${styles.card} ${styles.receiptCard} ${printingId === p.id ? styles.printingCard : ''}`}
              >
                <div className={styles.receiptHeader}>
                  <h4>Чек №{idx + 1}</h4>
                  <span>{new Date(p.created_at).toLocaleDateString()}</span>
                </div>
                <div className={styles.receiptBody}>
                  <div className={styles.receiptRow}>
                    <span>Автомобиль:</span>
                    <strong>{p.car_brand} {p.car_model} ({p.car_year})</strong>
                  </div>
                  <div className={styles.receiptRow}>
                    <span>Стоимость:</span>
                    <strong>{p.price.toLocaleString()} ₽</strong>
                  </div>
                  <div className={styles.receiptRow}>
                    <span>Тип оплаты:</span>
                    <strong>{p.payment_method === 'credit' ? 'Автокредит' : 'Карта'}</strong>
                  </div>
                </div>
                <button className={styles.printBtn} onClick={() => handlePrintReceipt(p.id)}>
                  Распечатать чек
                </button>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Вы еще не совершали покупок.</p>
        );

      case 'test_drives':
        return testDrives.length > 0 ? (
          <div className={styles.cardsGrid}>
            {testDrives.map((td) => (
              <div key={td.id} className={styles.card}>
                <div className={styles.cardHeader}>
                  <h3>{td.car_brand} {td.car_model}</h3>
                  <span className={`${styles.status} ${styles[td.status]}`}>{td.status === 'completed' ? 'Завершен' : td.status === 'cancelled' ? 'Отменен' : 'Ожидает'}</span>
                </div>
                <div className={styles.cardBody}>
                  <p>Дата: {new Date(td.date).toLocaleDateString()}</p>
                  <p>Время: {td.time}</p>
                  {td.status === 'completed' && !td.has_review && reviewForm.test_drive_id !== td.id && (
                    <button className={styles.actionBtn} onClick={() => setReviewForm(prev => ({ ...prev, test_drive_id: td.id }))}>Оставить отзыв</button>
                  )}
                  {reviewForm.test_drive_id === td.id && (
                    <form onSubmit={handleReviewSubmit} className={styles.reviewForm}>
                      <div className={styles.formGroup}>
                        <label>Оценка (1-5)</label>
                        <select value={reviewForm.rating} onChange={(e) => setReviewForm(prev => ({ ...prev, rating: parseInt(e.target.value) }))}>
                          <option value="5">5 - Отлично</option>
                          <option value="4">4 - Хорошо</option>
                          <option value="3">3 - Нормально</option>
                          <option value="2">2 - Плохо</option>
                          <option value="1">1 - Ужасно</option>
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label>Комментарий</label>
                        <textarea value={reviewForm.comment} onChange={(e) => setReviewForm(prev => ({ ...prev, comment: e.target.value }))} required />
                      </div>
                      <div className={styles.btnRow}>
                        <button type="submit" className={styles.saveBtn}>Отправить</button>
                        <button type="button" className={styles.cancelBtn} onClick={() => setReviewForm(prev => ({ ...prev, test_drive_id: null }))}>Отмена</button>
                      </div>
                    </form>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас нет записей на тест-драйв.</p>
        );

      case 'loans':
        return loans.length > 0 ? (
          <div className={styles.cardsGrid}>
            {loans.map((l) => (
              <div key={l.id} className={styles.card}>
                <div className={styles.cardHeader}>
                  <h3>{l.car_brand} {l.car_model}</h3>
                  <span className={`${styles.status} ${styles[l.status]}`}>
                    {l.status === 'approved' ? 'Одобрен' : l.status === 'rejected' ? 'Отклонен' : 'На рассмотрении'}
                  </span>
                </div>
                <div className={styles.cardBody}>
                  <p>Сумма кредита: {l.amount.toLocaleString()} ₽</p>
                  <p>Срок: {l.term} месяцев</p>
                  <p>Ставка: {l.rate}%</p>
                  <p>Ежемесячный платеж: {l.monthly_payment.toLocaleString()} ₽</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас нет заявок на кредит.</p>
        );

      case 'favorites':
        return favorites.length > 0 ? (
          <div className={styles.cardsGrid}>
            {favorites.map((f) => (
              <div key={f.id} className={styles.card}>
                <img src={getImageUrl(f.image_url || '/images/default-car.jpg')} alt={f.model} className={styles.cardImg} />
                <div className={styles.cardBody}>
                  <h3>{f.brand} {f.model}</h3>
                  <p>{f.price.toLocaleString()} ₽</p>
                  <div className={styles.btnRow}>
                    <Link to={`/cars/${f.id}`} className={styles.viewLink}>Подробнее</Link>
                    <button className={styles.removeBtn} onClick={() => handleRemoveFavorite(f.id)}>Удалить</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Список избранного пуст.</p>
        );

      case 'compare':
        return compareIds.length > 0 ? (
          <div className={styles.compareSection}>
            <p>У вас выбрано моделей для сравнения: {compareIds.length}</p>
            <Link to="/compare" className={styles.compareGoBtn}>Перейти к сравнению</Link>
            <div className={styles.cardsGrid} style={{ marginTop: '1rem' }}>
              {JSON.parse(localStorage.getItem('compareList') || '[]').map((c) => (
                <div key={c.id} className={styles.card}>
                  <div className={styles.cardBody}>
                    <h4>{c.brand} {c.model}</h4>
                    <p>{c.price.toLocaleString()} ₽</p>
                    <button className={styles.removeBtn} onClick={() => handleRemoveCompare(c.id)}>Убрать</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <p className={styles.empty}>Список сравнения пуст.</p>
        );

      case 'notifications':
        return notifications.length > 0 ? (
          <div className={styles.cardsGrid}>
            {notifications.map((n, idx) => {
              const msgText = typeof n === 'string' ? n : n.message;
              return (
                <div key={`notification-${idx}`} className={`${styles.card} ${styles.notificationCard}`}>
                  <div className={styles.cardBody}>{msgText}</div>
                </div>
              );
            })}
            <button className={styles.clearBtn} onClick={clearNotifications}>
              Очистить логи уведомлений
            </button>
          </div>
        ) : (
          <p className={styles.empty}>Новых уведомлений нет.</p>
        );

      default:
        return null;
    }
  };

  if (loading) return <div className={styles.loading}>Синхронизация данных профиля...</div>;

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <h2 className={styles.title}>Личный кабинет – {user?.full_name || 'Клиент'}</h2>
      
      <div className={styles.tabs}>
        {tabs.map(tab => (
          <button
            key={`tab-btn-${tab.key}`}
            className={`${styles.tab} ${activeTab === tab.key ? styles.active : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            {tab.label} {tab.key === 'compare' && compareIds.length > 0 && `(${compareIds.length})`}
          </button>
        ))}
      </div>

          <div className={styles.tabContentWindow}>
            <AnimatePresence mode="wait">
              <motion.div
                key={activeTab}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
              >
                {renderTabContent()}
              </motion.div>
            </AnimatePresence>
          </div>
    </motion.div>
  );
};

export default UserDashboard;
